// Types for content/textbook/index.json (generated by content/scripts/textbook/build_index.py).
export type Lang = "bn" | "en";
export type BlockKind = "let_us_do" | "exercise" | "task" | "let_us_try";

export interface SubItem { label: string; text_en: string | null; text_bn: string | null }
export interface Question {
  number: number; printed_page: number; pdf_page: number;
  text_en: string | null; text_bn: string | null;
  text_source: "ocr" | "manual"; text_verified: boolean; sub_items: SubItem[];
}
export interface Block {
  id: string; kind: BlockKind; number: number | null; set_index?: number;
  chapter: number; lesson_id: string | null; label_en: string; label_bn: string;
  section_en?: string | null; section_bn?: string | null;
  printed_pages: number[]; pdf_pages: number[]; verified: boolean; note?: string;
  questions: Question[];
}
export interface Lesson {
  id: string; number: number; title_en: string; title_bn: string;
  title_bn_source: "printed_heading" | "derived"; concept_id: string;
  printed_pages: [number, number]; pdf_pages: [number, number]; block_ids: string[];
}
export interface Chapter {
  number: number; title_en: string; title_bn: string;
  printed_pages: [number, number]; pdf_pages: [number, number]; lessons: Lesson[];
  let_us_do_block_ids: string[]; let_us_try_block_ids: string[]; verified: boolean;
}
export interface TextbookIndex {
  schema_version: number;
  book: {
    id: string; title_en: string; title_bn: string; grade: number; subject: string; edition: string;
    source_label_en: string; source_label_bn: string;
    page_map: { ranges: { pdf_from: number; pdf_to: number; printed_from: number; printed_to: number; offset: number }[] };
    [k: string]: unknown;
  };
  naming: unknown;
  chapters: Chapter[];
  blocks: Block[];
}
